{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    payload = case.get("payload", case)
    if not isinstance(payload, dict):
        raise ValueError("payload must be an object")

    required = ("nodes", "core_distance", "distances")
    if any(name not in payload for name in required):
        raise ValueError("missing required field")

    nodes = payload["nodes"]
    core_distance = payload["core_distance"]
    distances = payload["distances"]
    if not isinstance(nodes, list) or not isinstance(core_distance, dict) or not isinstance(distances, list):
        raise ValueError("invalid required field type")
    if not nodes:
        raise ValueError("nodes must not be empty")
    if any(not isinstance(node, str) or not node for node in nodes):
        raise ValueError("node identifiers must be non-empty strings")
    if len(set(nodes)) != len(nodes):
        raise ValueError("node identifiers must be unique")
    if set(core_distance) != set(nodes):
        raise ValueError("core_distance keys must exactly match nodes")

    ordered_nodes = sorted(nodes)
    normalized_core = {}
    for node in ordered_nodes:
        value = core_distance[node]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("core distance must be numeric")
        value = float(value)
        if not math.isfinite(value) or value < 0:
            raise ValueError("core distance must be finite and non-negative")
        normalized_core[node] = value

    edges = []
    seen_pairs = set()
    node_set = set(nodes)
    for position, entry in enumerate(distances):
        if not isinstance(entry, (list, tuple)) or len(entry) != 3:
            raise ValueError("each distance entry must contain two endpoints and a distance")
        left, right, distance = entry
        if left not in node_set or right not in node_set or left == right:
            raise ValueError("invalid distance endpoint")
        if isinstance(distance, bool) or not isinstance(distance, (int, float)):
            raise ValueError("distance must be numeric")
        distance = float(distance)
        if not math.isfinite(distance) or distance < 0:
            raise ValueError("distance must be finite and non-negative")
        if right < left:
            left, right = right, left
        pair = (left, right)
        if pair in seen_pairs:
            raise ValueError("duplicate undirected distance entry")
        seen_pairs.add(pair)
        reachability = max(normalized_core[left], normalized_core[right], distance)
        edges.append({
            "left": left,
            "right": right,
            "distance": distance,
            "mutual_reachability": reachability,
            "source_position": position,
        })

    edges.sort(key=lambda edge: (edge["mutual_reachability"], edge["left"], edge["right"]))

    parent = {node: node for node in ordered_nodes}
    rank = {node: 0 for node in ordered_nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left, right):
        root_left = find(left)
        root_right = find(right)
        if root_left == root_right:
            return False
        if rank[root_left] < rank[root_right]:
            root_left, root_right = root_right, root_left
        parent[root_right] = root_left
        if rank[root_left] == rank[root_right]:
            rank[root_left] += 1
        return True

    selected = []
    for edge in edges:
        if union(edge["left"], edge["right"]):
            selected.append(edge)
            if len(selected) == len(nodes) - 1:
                break

    if len(selected) != len(nodes) - 1:
        raise ValueError("distance graph is disconnected")

    def public_edge(edge):
        return {
            "left": edge["left"],
            "right": edge["right"],
            "distance": edge["distance"],
            "mutual_reachability": edge["mutual_reachability"],
            "source_position": edge["source_position"],
        }

    return {
        "core_distance": {node: normalized_core[node] for node in ordered_nodes},
        "mutual_reachability_edges": [public_edge(edge) for edge in edges],
        "mst_edges": [public_edge(edge) for edge in selected],
        "total_weight": sum(edge["mutual_reachability"] for edge in selected),
    }
